const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const prescottAZ = ee.Geometry.Point([-112.4685, 34.5400]);
  const startDate = '2017-06-01';
  const endDate = '2017-07-01'; // Exclusive end date

  // 2. Data Acquisition & Check
  const nldas = ee.ImageCollection('NASA/NLDAS/FORA0125_H002')
    .filterDate(startDate, endDate)
    .filterBounds(prescottAZ)
    .select('temperature');

  const collectionSize = nldas.size().getInfo();
  if (collectionSize === 0) {
    console.log(`Evidence: No NLDAS images found for June 2017.`);
    console.log('A'); // NLDAS has continuous coverage; a 0 count is a system/query error, not a data gap. Let's be optimistic.
    return;
  }
  console.log(`Evidence: Found ${collectionSize} hourly NLDAS images for June 2017.`);

  // 3. Processing
  // Find the maximum temperature in Kelvin over the month.
  const maxTempK = nldas.max();

  // 4. Calculation
  const tempStats = maxTempK.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: prescottAZ,
    scale: 1000, // NLDAS native resolution is ~12.5km
    maxPixels: 1e9
  });

  const maxKelvin = tempStats.get('temperature').getInfo();

  // 5. Validation & Final Answer
  if (maxKelvin === null) {
    console.log('Evidence: Could not calculate maximum temperature. Result was null.');
    console.log('C3');
    return;
  }

  // Convert Kelvin to Fahrenheit: (K − 273.15) × 9/5 + 32 = °F
  const maxFahrenheit = (maxKelvin - 273.15) * 1.8 + 32;

  console.log(`Evidence: Maximum temperature in Kelvin: ${maxKelvin.toFixed(2)} K.`);
  console.log(`Evidence: Maximum temperature in Fahrenheit: ${maxFahrenheit.toFixed(2)} °F.`);

  if (maxFahrenheit > 100) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred during the analysis:', err);
    console.log('D');
});
